corrected_code:
@router.post("/sso/saml/slo")
async def saml_single_logout(
    request: Request,
    session_cache: Redis = Depends(get_redis_client)
):
    req_data = await prepare_fastapi_request_for_saml(request)
    auth = OneLogin_Saml2_Auth(req_data, get_global_saml_settings())
    url = auth.process_slo(keep_local_session=True)

    name_id = auth.get_nameid()
    issuer = auth.get_issuer()
    if name_id and issuer:
        pattern = f"session:{issuer}:{name_id}:*"
        keys = await session_cache.keys(pattern)
        if keys:
            await session_cache.delete(*keys)

    return RedirectResponse(url or "/login")
